#include "buffer/lru_k_replacer.h"
#include "common/exception.h"

namespace bustub {

LRUKReplacer::LRUKReplacer(size_t num_frames, size_t k) : replacer_size_(num_frames), k_(k) {}

auto LRUKReplacer::Evict() -> std::optional<frame_id_t> {
  std::lock_guard<std::mutex> lock(latch_);
  std::optional<frame_id_t> victim = std::nullopt;
  size_t max_kdist = 0;
  size_t victim_oldest = 0;
  bool victim_inf = false;
  for (auto &[fid, node] : node_store_) {
    if (!node.is_evictable_) continue;
    bool inf = node.history_.size() < k_;
    size_t kdist = 0;
    size_t oldest = node.history_.front();
    if (!inf) {
      auto it = node.history_.rbegin();
      std::advance(it, k_ - 1);
      kdist = current_timestamp_ - *it;
    }
    if (!victim.has_value()) {
      victim = fid; victim_inf = inf; max_kdist = kdist; victim_oldest = oldest;
      continue;
    }
    bool better = false;
    if (inf && !victim_inf) better = true;
    else if (inf && victim_inf) better = oldest < victim_oldest;
    else if (!inf && !victim_inf) better = kdist > max_kdist;
    if (better) { victim = fid; victim_inf = inf; max_kdist = kdist; victim_oldest = oldest; }
  }
  if (victim.has_value()) {
    node_store_.erase(*victim);
    curr_size_--;
  }
  return victim;
}

void LRUKReplacer::RecordAccess(frame_id_t frame_id, [[maybe_unused]] AccessType access_type) {
  std::lock_guard<std::mutex> lock(latch_);
  if (static_cast<size_t>(frame_id) >= replacer_size_) {
    throw Exception("invalid frame id");
  }
  auto &node = node_store_[frame_id];
  node.fid_ = frame_id;
  node.k_ = k_;
  node.history_.push_back(current_timestamp_);
  if (node.history_.size() > k_) node.history_.pop_front();
  current_timestamp_++;
}

void LRUKReplacer::SetEvictable(frame_id_t frame_id, bool set_evictable) {
  std::lock_guard<std::mutex> lock(latch_);
  if (static_cast<size_t>(frame_id) >= replacer_size_) {
    throw Exception("invalid frame id");
  }
  auto it = node_store_.find(frame_id);
  if (it == node_store_.end()) return;
  if (it->second.is_evictable_ == set_evictable) return;
  it->second.is_evictable_ = set_evictable;
  if (set_evictable) curr_size_++; else curr_size_--;
}

void LRUKReplacer::Remove(frame_id_t frame_id) {
  std::lock_guard<std::mutex> lock(latch_);
  auto it = node_store_.find(frame_id);
  if (it == node_store_.end()) return;
  if (!it->second.is_evictable_) {
    throw Exception("removing non-evictable frame");
  }
  node_store_.erase(it);
  curr_size_--;
}

auto LRUKReplacer::Size() -> size_t {
  std::lock_guard<std::mutex> lock(latch_);
  return curr_size_;
}

}  // namespace bustub
